const bases = $('09. Preparar Alerta de Duplicidade ao Fiscal').all();
const respostasFollowup = $input.all();

function normalizarTexto(item) {
  const bruto = String(item?.content || item?.comment || item?.name || '');
  return bruto.toUpperCase().replace(/\s+/g, ' ').trim();
}

function extrairChave(texto) {
  const m = texto.match(/CHAVE_DUPLICIDADE\s*=\s*([A-Z0-9\-_]+)/i);
  return m ? String(m[1]).toUpperCase() : '';
}

function decidirPorTexto(texto) {
  if (/DECISAO_DUPLICIDADE\s*=\s*CONFIRMAR/.test(texto)) return 'confirma_duplicado';
  if (/DECISAO_DUPLICIDADE\s*=\s*NAO_DUPLICADO/.test(texto)) return 'nao_duplicado';
  if (/\bCONFIRMAR_DUPLICIDADE\b/.test(texto)) return 'confirma_duplicado';
  if (/\bREJEITAR_DUPLICIDADE\b/.test(texto)) return 'nao_duplicado';
  return '';
}

return respostasFollowup.map((entrada, idx) => {
  const base = bases[idx]?.json || {};
  const chaveEsperada = String(base._dup_chave || '').toUpperCase();
  const bruto = entrada.json;
  const lista = Array.isArray(bruto)
    ? bruto
    : (Array.isArray(bruto.data) ? bruto.data : (Array.isArray(bruto['hydra:member']) ? bruto['hydra:member'] : []));

  const elegiveis = lista
    .map((f) => {
      const texto = normalizarTexto(f);
      const decisao = decidirPorTexto(texto);
      return {
        data: new Date(f?.date_mod || f?.date_creation || f?.date || 0).getTime() || 0,
        texto,
        chave: extrairChave(texto),
        decisao,
      };
    })
    .filter((f) => !!f.decisao)
    .filter((f) => {
      if (!chaveEsperada) return true;
      if (!f.chave) return true;
      return f.chave === chaveEsperada;
    })
    .sort((a, b) => b.data - a.data);

  if (elegiveis.length === 0) {
    return {
      json: {
        ...base,
        decisao_fiscal: '',
        origem_decisao: 'sem_registro'
      }
    };
  }

  const ultimo = elegiveis[0];
  return {
    json: {
      ...base,
      decisao_fiscal: ultimo.decisao,
      origem_decisao: 'followup_glpi',
      _decisao_texto: ultimo.texto,
      _decisao_chave: ultimo.chave || ''
    }
  };
});

return $input.all().map((item, i) => {
  const json = item.json || {};
  const tentativa = Number(json.tentativa_reprocesso_dup || 0) + 1;
  const reprocessar = tentativa <= 2;

  // O nó da IA exclui os dados quando falha. Vamos restaurá-los!
  // Como as execuções item a item mantêm a ordem, tentamos buscar no runIndex ou pelo backup salvo em E1 Log.
  // Graças a isso, a IA não vai receber campos vazios na requisição.
  const chamadoRecuperado = $('04. Estruturar Dados dos Chamados').itemMatching(i)?.json?.chamado_atual || json.chamado_atual || json._chamado_recuperado;
  const historicoRecuperado = $('04. Estruturar Dados dos Chamados').itemMatching(i)?.json?.historico_abertos || json.historico_abertos;

  return {
    json: {
      ...json,
      tentativa_reprocesso_dup: tentativa,
      reprocessar_dup: reprocessar,
      // INJETANDO OS DADOS DE VOLTA PARA O LOOP
      chamado_atual: chamadoRecuperado,
      historico_abertos: historicoRecuperado
    }
  };
});

return $input.all().map(item => {
  const tentativa = Number(item.json.tentativa_reprocesso_class || 0) + 1;
  return {
    json: {
      ...item.json,
      tentativa_reprocesso_class: tentativa,
      reprocessar_class: tentativa <= 1
    }
  };
});

// Processa todos os itens de entrada e extrai a lista de chamados retornada pelo GLPI
let todosChamados = [];

for (const item of $input.all()) {
  let dadosBrutos = item.json;
  let lista = [];

  if (Array.isArray(dadosBrutos.data)) lista = dadosBrutos.data;
  else if (dadosBrutos.body && Array.isArray(dadosBrutos.body.data)) lista = dadosBrutos.body.data;
  else if (Array.isArray(dadosBrutos)) lista = dadosBrutos;
  else if (Array.isArray(dadosBrutos['hydra:member'])) lista = dadosBrutos['hydra:member'];
  else {
    for (const key in dadosBrutos) {
      if (Array.isArray(dadosBrutos[key])) { lista = dadosBrutos[key]; break; }
    }
    if (lista.length === 0) lista = [dadosBrutos];
  }

  lista.forEach(c => todosChamados.push(c));
}

if (todosChamados.length === 0) {
  return [{ json: { erro: 'Nenhum chamado encontrado', total: 0 } }];
}

const LIMITE_CHAMADOS_TRIAGEM = 0; // 0 = sem limite
const MAX_HISTORICO_COMPARACAO = 25;
const DIAS_FECHADO_MESES = 120;
const DIAS_TRIAGEM_ATIVA = 7;
const DIAS_CONCLUIDO_30 = 30;
const agora = new Date();
const corteFechadoMeses = new Date(agora.getTime() - DIAS_FECHADO_MESES * 24 * 60 * 60 * 1000);
const corteTriagemAtiva = new Date(agora.getTime() - DIAS_TRIAGEM_ATIVA * 24 * 60 * 60 * 1000);
const corteConcluido30 = new Date(agora.getTime() - DIAS_CONCLUIDO_30 * 24 * 60 * 60 * 1000);

const STATUS_LABELS = { 1: 'Novo', 2: 'Processando Atribuido', 3: 'Processando Planejado', 4: 'Pendente', 5: 'Finalizado', 6: 'Fechado' };

function statusNumero(status) {
  if (typeof status === 'number') return status;
  const txt = String(status || '').toLowerCase();
  if (txt.includes('novo') || txt === '1') return 1;
  if (txt.includes('atribu') || txt === '2') return 2;
  if (txt.includes('planejad') || txt === '3') return 3;
  if (txt.includes('pendent') || txt === '4') return 4;
  if (txt.includes('finaliz') || txt.includes('solucion') || txt === '5') return 5;
  if (txt.includes('fechado') || txt.includes('close') || txt === '6') return 6;
  return Number(status) || null;
}

function toEpoch(valor) {
  const d = new Date(valor);
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
}

function entraNoRecorteHistorico(chamado) {
  const dAbertura = new Date(chamado.data_abertura);
  const dataValida = !Number.isNaN(dAbertura.getTime());

  // Chamados em andamento continuam visiveis para comparacao de duplicidade.
  if ([2, 3, 4].includes(chamado.status_num)) return true;

  // Concluido (5): somente ultimos 30 dias.
  if (chamado.status_num === 5) {
    return dataValida && dAbertura >= corteConcluido30;
  }

  // Fechado (6): janela maior de 4 meses.
  if (chamado.status_num === 6) {
    return dataValida && dAbertura >= corteFechadoMeses;
  }

  return false;
}

function entraNaTriagemAtiva(chamado) {
  if (![1, 2].includes(chamado.status_num)) return false;

  const dAbertura = new Date(chamado.data_abertura);
  const dataValida = !Number.isNaN(dAbertura.getTime());
  return dataValida && dAbertura >= corteTriagemAtiva;
}

function extrairTipoServico(c) {
  return c.tipo_servico || c.tipo || c.service_type || c['14'] || c.itilcategories_id || c['itilcategories_id'] || '';
}

const todosLimpos = todosChamados.map(c => {
  const status_num = statusNumero(c['12'] || c.status);
  const dataAbertura = c['15'] || c.date || '';
  return {
    id: c['2'] || c.id,
    titulo: c['1'] || c.name || '',
    status: c['12'] || c.status,
    status_num,
    status_nome: STATUS_LABELS[status_num] || 'Desconhecido',
    tipo_servico: extrairTipoServico(c),
    descricao: (c['21'] || c.content || '').replace(/<[^>]*>/g, '').trim(),
    localizacao: c['83'] || c.locations_id || '',
    data_abertura: dataAbertura,
    data_hora_abertura: dataAbertura,
    solicitante: c['4'] || c.users_id_recipient || '',
    email_solicitante: c['22'] || ''
  };
});

const elegiveisHistorico = todosLimpos.filter(entraNoRecorteHistorico);

let chamadosParaTriar = todosLimpos
  .filter(entraNaTriagemAtiva)
  .sort((a, b) => toEpoch(b.data_abertura) - toEpoch(a.data_abertura));

let ticketIdEvento = null;
try {
  const evento = $('02b. Preparar Entrada Webhook').first().json || {};
  const n = Number(evento._ticket_id_evento);
  if (Number.isFinite(n) && n > 0) ticketIdEvento = n;
} catch {}

if (ticketIdEvento) {
  const alvo = todosLimpos.find((c) => String(c.id) === String(ticketIdEvento));
  if (!alvo) {
    return [{ json: { erro: 'Chamado do webhook nao encontrado na busca de interesse', ticket_id_evento: ticketIdEvento, total_historico: elegiveisHistorico.length } }];
  }
  chamadosParaTriar = [alvo];
}

if (LIMITE_CHAMADOS_TRIAGEM > 0 && !ticketIdEvento) chamadosParaTriar = chamadosParaTriar.slice(0, LIMITE_CHAMADOS_TRIAGEM);

if (chamadosParaTriar.length === 0) {
  return [{ json: { erro: 'Nenhum chamado elegivel para triagem ativa de duplicidade', total_historico: elegiveisHistorico.length } }];
}

let itemsDeSaida = [];

for (let i = 0; i < chamadosParaTriar.length; i++) {
  const chamadoAtual = chamadosParaTriar[i];
  const historicoCompacto = elegiveisHistorico
    .filter(c => String(c.id) !== String(chamadoAtual.id))
    .sort((a, b) => toEpoch(b.data_abertura) - toEpoch(a.data_abertura))
    .slice(0, MAX_HISTORICO_COMPARACAO);

  itemsDeSaida.push({
    json: {
      chamado_atual: chamadoAtual,
      historico_abertos: historicoCompacto,
      _split_index: i + 1,
      _split_total: chamadosParaTriar.length,
      _chamado_recuperado: chamadoAtual
    }
  });
}

return itemsDeSaida;

const entradas = $input.all();
const originais = $('04. Estruturar Dados dos Chamados').all();

function tentarParseJson(texto) {
  if (typeof texto !== 'string') return null;
  try {
    return JSON.parse(texto);
  } catch {
    return null;
  }
}

function extrairCarga(jsonEntrada) {
  let dados = jsonEntrada;

  const textoPart = dados?.content?.parts?.[0]?.text;
  if (typeof textoPart === 'string') {
    const parsed = tentarParseJson(textoPart);
    if (parsed !== null) dados = parsed;
  }

  const textoMsg = dados?.message?.content;
  if (typeof textoMsg === 'string') {
    const parsed = tentarParseJson(textoMsg);
    if (parsed !== null) dados = parsed;
  }

  return dados;
}

function pareceResultadoDuplicidade(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (obj.duplicidade && typeof obj.duplicidade === 'object') return true;
  if (obj.eh_duplicado !== undefined) return true;
  if (obj.potencial_duplicata !== undefined) return true;
  return false;
}

function extrairRegistrosOrdenados(payload) {
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.resultados)) return payload.resultados;
  if (payload && Array.isArray(payload.items)) return payload.items;

  if (payload && Array.isArray(payload.data)) {
    const data = payload.data;
    if (data.every((x) => pareceResultadoDuplicidade(x) || (x && x.chamado))) {
      return data;
    }
  }

  return [payload];
}

function parseBool(valor) {
  if (typeof valor === 'boolean') return valor;
  if (typeof valor === 'number') return valor !== 0;
  if (typeof valor === 'string') {
    const v = valor.trim().toLowerCase();
    if (['true', '1', 'sim', 'yes', 'y', 'verdadeiro'].includes(v)) return true;
    if (['false', '0', 'nao', 'não', 'no', 'n', 'falso'].includes(v)) return false;
  }
  return false;
}

function normalizarChamado(chamado, original) {
  const base = chamado && typeof chamado === 'object' ? chamado : {};
  const ref = original && typeof original === 'object' ? original : {};
  return { ...ref, ...base };
}

function dataMs(valor) {
  const d = new Date(valor || '');
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
}

const registrosIA = [];
for (const entrada of entradas) {
  const carga = extrairCarga(entrada.json || {});
  const regs = extrairRegistrosOrdenados(carga);
  if (regs.length === 0) registrosIA.push(carga);
  else registrosIA.push(...regs);
}

const saida = [];
const totalBase = originais.length;

for (let i = 0; i < totalBase; i++) {
  const base = originais[i]?.json || {};
  const original = base.chamado_atual || null;
  const historico = Array.isArray(base.historico_abertos) ? base.historico_abertos : [];
  const bruto = JSON.stringify(registrosIA[i] || {}).slice(0, 2000);
  const dados = registrosIA[i] && typeof registrosIA[i] === 'object' ? registrosIA[i] : {};

  const dupBase = dados.duplicidade && typeof dados.duplicidade === 'object' ? dados.duplicidade : {};
  const temEstrutura = pareceResultadoDuplicidade(dados);

  if (!temEstrutura) {
    saida.push({
      json: {
        ...base,
        chamado: original || { id: 'estrutura_invalida' },
        duplicidade: {
          eh_duplicado: false,
          chamado_referencia_id: null,
          caracteristicas_match: [],
          justificativa_para_fiscal: 'Resposta da IA sem estrutura esperada.'
        },
        'Duplicado?': {
          valor: 'Nao',
          caracteristicas: [],
          chamado_match: null
        },
        acao_duplicidade: {
          manter_chamado_id: original?.id || null,
          fechar_chamado_id: null,
          criterio: 'sem_duplicidade'
        },
        _erro: true,
        tipo_erro: 'estrutura_resposta_inesperada',
        payload_ia_bruto: bruto
      }
    });
    continue;
  }

  const chamado = normalizarChamado(dados.chamado, original);
  const ehDuplicadoValor = dupBase.eh_duplicado !== undefined
    ? dupBase.eh_duplicado
    : (dados.eh_duplicado !== undefined ? dados.eh_duplicado : dados.potencial_duplicata);
  const ehDuplicado = parseBool(ehDuplicadoValor) === true;

  const refRaw = dupBase.chamado_referencia_id !== undefined
    ? dupBase.chamado_referencia_id
    : dados.chamado_referencia_id;
  const refNum = Number(refRaw);
  const referenciaId = Number.isFinite(refNum) && refNum > 0 ? refNum : null;

  const caracteristicas = Array.isArray(dupBase.caracteristicas_match)
    ? dupBase.caracteristicas_match
    : (Array.isArray(dados.caracteristicas_match) ? dados.caracteristicas_match : []);

  const justificativa = dupBase.justificativa_para_fiscal
    || dados.justificativa_para_fiscal
    || 'Sem justificativa';

  let manterId = referenciaId;
  let fecharId = chamado?.id || null;

  if (ehDuplicado && referenciaId) {
    const match = historico.find((h) => String(h.id) === String(referenciaId));
    const dataAtual = dataMs(chamado?.data_hora_abertura || chamado?.data_abertura);
    const dataMatch = dataMs(match?.data_hora_abertura || match?.data_abertura);

    if (dataAtual > 0 && dataMatch > 0 && dataAtual <= dataMatch) {
      manterId = chamado?.id || referenciaId;
      fecharId = referenciaId;
    }
  }

  if (!ehDuplicado) {
    manterId = chamado?.id || null;
    fecharId = null;
  }

  saida.push({
    json: {
      ...base,
      chamado: chamado.id ? chamado : (original || { id: 'desconhecido' }),
      duplicidade: {
        eh_duplicado: ehDuplicado,
        chamado_referencia_id: referenciaId,
        caracteristicas_match: caracteristicas,
        justificativa_para_fiscal: justificativa
      },
      'Duplicado?': {
        valor: ehDuplicado ? 'Sim' : 'Nao',
        caracteristicas: caracteristicas,
        chamado_match: referenciaId
      },
      acao_duplicidade: {
        manter_chamado_id: manterId,
        fechar_chamado_id: fecharId,
        criterio: ehDuplicado ? 'manter_mais_antigo' : 'sem_duplicidade'
      },
      _erro: false
    }
  });
}

return saida;

const MODO_TESTE = false;

return $input.all().map((entrada) => {
  const item = entrada.json;
  const chamado = item.chamado || {};
  const dup = item.duplicidade || {};
  const resumoDup = item['Duplicado?'] || {};
  const acao = item.acao_duplicidade || {};

  const chamadoDecisaoId = chamado.id || null;
  const chamadoFecharId = acao.fechar_chamado_id || chamado.id || null;
  const chamadoManterId = acao.manter_chamado_id || dup.chamado_referencia_id || chamado.id || null;
  const chaveDuplicidade = ['DUP', chamadoDecisaoId || 'NA', chamadoFecharId || 'NA', chamadoManterId || 'NA'].join('-');

  const comandoConfirmar = 'DECISAO_DUPLICIDADE=CONFIRMAR CHAVE_DUPLICIDADE=' + chaveDuplicidade;
  const comandoNaoDuplicado = 'DECISAO_DUPLICIDADE=NAO_DUPLICADO CHAVE_DUPLICIDADE=' + chaveDuplicidade;

  return {
    json: {
      ...item,
      _modo_teste: MODO_TESTE,
      _chamado_id: chamadoDecisaoId,
      _chamado_fechar_id: chamadoFecharId,
      _chamado_manter_id: chamadoManterId,
      _chamado_ref_id: chamadoManterId,
      _dup_chave: chaveDuplicidade,
      _comando_confirmar: comandoConfirmar,
      _comando_nao_duplicado: comandoNaoDuplicado,
      _formulario_titulo: 'Alerta de Duplicidade - Chamado #' + (chamadoDecisaoId || 'N/A'),
      _formulario_mensagem: 'A IA identificou possivel duplicidade. Chamado para decisao: #' + (chamadoDecisaoId || 'N/A') + '.',
      _mensagem_followup_fiscal: [
        '[TRIAGEM_IA][PENDENTE_DECISAO_DUPLICIDADE]',
        'Chamado para decisao: #' + (chamadoDecisaoId || 'N/A') + ' - ' + (chamado.titulo || ''),
        'Chamado com match: #' + (resumoDup.chamado_match || dup.chamado_referencia_id || 'N/A'),
        'Regra de fechamento: manter #' + (chamadoManterId || 'N/A') + ' e fechar #' + (chamadoFecharId || 'N/A'),
        'Justificativa IA: ' + (dup.justificativa_para_fiscal || 'Sem justificativa'),
        '',
        'Fiscal: para decidir, adicione um novo acompanhamento neste chamado com um dos comandos abaixo (copiar e colar):',
        comandoConfirmar,
        comandoNaoDuplicado,
        '',
        'Obs: o workflow verifica periodicamente e executa a decisao automaticamente.'
      ].join('\n')
    }
  };
});

let saida = [];
for (const item of $input.all()) {
  let json = item.json;
  let chamado = json.chamado;
  if (!chamado && json._chamado_id) { chamado = { id: json._chamado_id }; }
  saida.push({ json: { chamado: chamado || json, origem: json.acao === 'SEGUE_PARA_CLASSIFICACAO' ? 'fiscal_rejeitou_duplicidade' : 'nao_duplicado' } });
}
return saida;

